#!/usr/bin/env node
import './security/remote-access-portals.js';
// Pure content/catalog gate; actual HTTP fixture acceptance is a separate required gate.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import crypto from 'node:crypto';
import { EXPOSURE_RULES, EXPOSURE_FAMILIES, RULES_BY_ID, EXPOSURE_INDICATORS, exposurePresentation } from '../shared/exposure/catalog.js';
import { evaluateExposure, exposureEvaluatorProgramSource } from '../shared/exposure/evaluate.js';
import { planExposureChecks, discoverExposureReferences } from '../shared/exposure/discovery.js';
import { sha256Text, isSafeExposurePath, isRulePathAllowed, safeExposureUrl } from '../shared/exposure/redaction.js';
import { EXPOSURE_FIXTURES, EXPOSURE_CONTROL_FIXTURES, EXPOSURE_SYNTHETIC_SECRET } from './fixtures/exposure/cases.js';
let count = 0;
function check(label, fn) { try { fn(); count++; } catch(e) { console.error('FAIL',label); throw e; } }
const origin = 'https://fixture.example.test';
const controls = EXPOSURE_CONTROL_FIXTURES;
const run = (ruleId, body, rest = {}) => evaluateExposure({rule:ruleId, response:{url:origin+RULES_BY_ID[ruleId].paths[0],status:200,body,...rest},controls});
const positive = id=>EXPOSURE_FIXTURES.find(f=>f.ruleId===id&&f.polarity==='positive');
const indicators = new Set(EXPOSURE_INDICATORS);
check('all nine families and unique rule IDs',()=>{assert.equal(new Set(EXPOSURE_RULES.map(r=>r.family)).size,9);assert.deepEqual(new Set(EXPOSURE_RULES.map(r=>r.family)),new Set(EXPOSURE_FAMILIES));assert.equal(new Set(EXPOSURE_RULES.map(r=>r.id)).size,EXPOSURE_RULES.length);});
for (const rule of EXPOSURE_RULES) {
  check(rule.id+' positive and negative fixture coverage',()=>{assert(EXPOSURE_FIXTURES.some(f=>f.ruleId===rule.id&&f.polarity==='positive'));assert(EXPOSURE_FIXTURES.some(f=>f.ruleId===rule.id&&f.polarity==='negative'));});
  check(rule.id+' executable catalog contract',()=>{assert.equal(rule.active,true);assert(rule.version>0);for(const k of ['applicability','title','risk'])assert(rule[k]);for(const k of ['positive','negative','uncertain'])assert(rule.evidence[k]);assert(rule.maxCost.requests===1+rule.maxCost.redirects+rule.maxCost.retries);assert(rule.maxCost.bytes<=32768);for(const p of rule.paths)assert(isRulePathAllowed(rule,p),p);});
  for (const status of [401,403,429,500,502]) check(rule.id+' denial/status '+status,()=>{const r=run(rule.id,positive(rule.id).body,{status});assert(!r.comparable);assert(!r.finding);assert(['blocked','uncertain'].includes(r.state));});
  check(rule.id+' transport failure never closes',()=>{assert.equal(run(rule.id,'',{error:'connection_reset'}).comparable,false);});
  check(rule.id+' missing negative controls never confirms',()=>{const r=evaluateExposure({rule:rule.id,response:{status:200,body:positive(rule.id).body,url:origin}});assert.equal(r.state,'uncertain');assert.equal(r.comparable,false);});
  check(rule.id+' bounded missing pattern stays uncertain',()=>{const r=run(rule.id,'incomplete',{truncated:true});assert.equal(r.state,'uncertain');assert.equal(r.comparable,false);});
  check(rule.id+' generic HTML never confirms',()=>{const r=run(rule.id,'<html><title>Welcome</title><body><main id="app">Loading application</main></body></html>');assert(!r.finding);});
  check(rule.id+' raw responses never returned',()=>{const r=run(rule.id,positive(rule.id).body,{headers:{'set-cookie':'secret=cm-secret-cookie'},url:origin+rule.paths[0]+'?token=cm-query-secret'});const text=JSON.stringify(r);for(const marker of [EXPOSURE_SYNTHETIC_SECRET,'cm-secret-cookie','cm-query-secret'])assert(!text.includes(marker));assert(!('body' in r));assert(!('headers' in r));});
}
for (const fixture of EXPOSURE_FIXTURES) check(fixture.id,()=>{const r=run(fixture.ruleId,fixture.body,{status:fixture.status});assert.equal(r.state,fixture.expectedState);for(const code of (r.finding||r.observation)?.evidence.indicators||[])assert(indicators.has(code),code);});
check('independently embedded evaluator matches every fixture',()=>{
  const sandbox=vm.createContext({URL,TextEncoder,TextDecoder,Uint8Array,DataView,Int32Array});vm.runInContext(exposureEvaluatorProgramSource(),sandbox);
  for(const f of EXPOSURE_FIXTURES){const input={rule:f.ruleId,response:{...f,url:origin+RULES_BY_ID[f.ruleId].paths[0]},controls};assert.equal(JSON.stringify(sandbox.evaluateExposure(input)),JSON.stringify(evaluateExposure(input)));}
});
check('SHA256 identity implementation matches platform',()=>{for(const value of ['','abc',origin,'Turkish İ and Unicode 🌍', 'x'.repeat(257)])assert.equal(sha256Text(value),crypto.createHash('sha256').update(value).digest('hex'));});
check('credential rotation does not create a fresh finding identity',()=>{const a=run('env-config',positive('env-config').body),b=run('env-config',positive('env-config').body.replace(EXPOSURE_SYNTHETIC_SECRET,'CmRotated-8391-Different'));assert(a.finding&&b.finding);assert.equal(a.finding.identity,b.finding.identity);});
check('distinct redacted paths retain distinct identities',()=>{const a=run('client-secret',positive('client-secret').body,{url:origin+'/assets/one.js'}),b=run('client-secret',positive('client-secret').body,{url:origin+'/assets/two.js'});assert.equal(a.finding.safeUrl,b.finding.safeUrl);assert.notEqual(a.finding.identity,b.finding.identity);});
check('dynamic soft-404 structure is uncertain',()=>{const body=n=>`<html><title>Page unavailable</title><body><main>Cannot locate /path${n}. Request ${n}</main></body></html>`;const r=evaluateExposure({rule:'env-config',response:{url:origin+'/.env',status:200,body:body(39)},controls:[{status:200,body:body(17)},{status:200,body:body(22)}]});assert.equal(r.state,'uncertain');});
// A sensitive path answering 451 (withheld) is never a definitive "not found" — and
// never a finding either: the content was not served to this requester.
check('451 on a sensitive path is uncertain, never not_found',()=>{for(const id of ['env-config','api-schema']){const r=run(id,positive(id).body,{status:451});assert.equal(r.state,'uncertain');assert.notEqual(r.state,'not_found');assert.equal(r.comparable,false);}});
check('SPA shell is uncertain',()=>{const body='<html><head><title>Application</title></head><body><div id="app"></div><script src="/main.js"></script></body></html>';const r=evaluateExposure({rule:'env-config',response:{url:origin+'/.env',status:200,body},controls:[{status:200,body},{status:200,body}]});assert.equal(r.reason,'soft_404_or_common_response');});
check('WAF with 200 is blocked',()=>assert.equal(run('env-config','<html><body>Verify you are human <div class="g-recaptcha"></div></body></html>').state,'blocked'));
check('401 negative control prevents false clean',()=>assert.equal(evaluateExposure({rule:'env-config',response:{status:404,url:origin},controls:[{status:401},{status:404}]}).comparable,false));
check('404 with valid controls can prove absence',()=>assert.equal(run('env-config','',{status:404}).comparable,true));
check('actual wrapped actuator secret raises severity, values are removed',()=>{const r=run('actuator-env',JSON.stringify({propertySources:[{name:'systemEnvironment',properties:{DATABASE_PASSWORD:{value:EXPOSURE_SYNTHETIC_SECRET}}}]}));assert.equal(r.finding.severity,'high');assert(!JSON.stringify(r).includes(EXPOSURE_SYNTHETIC_SECRET));});
check('public keys do not become secrets',()=>{for(const body of ['window.cfg={PUBLIC_KEY:"-----BEGIN PUBLIC KEY----- ABCD -----END PUBLIC KEY-----"};','window.cfg={apiKey:"AIza12345678901234567890123456789012345",SUPABASE_ANON_KEY:"eyJhbGciOiJIUzI1NiJ9.eyJyb2xlIjoiYW5vbiJ9.signature"};','window.cfg={stripe_publishable_key:"pk_live_123456789012345678901234"};'])assert.equal(run('client-secret',body).state,'not_found');});
check('real private key block is secret; no key body emitted',()=>{const body='window.cfg={private_key:`-----BEGIN '+'PRIVATE KEY-----\n'+'QWxhZGRpbjpPcGVuU2VzYW1l'.repeat(4)+'\n-----END '+'PRIVATE KEY-----`};';const r=run('client-secret',body);assert.equal(r.state,'finding');assert(r.finding.evidence.indicators.includes('private_key_block'));assert(!JSON.stringify(r).includes('QWxh'));});
check('documentation with realistic fake config does not confirm',()=>assert.equal(run('env-config','This is an example configuration\n'+positive('env-config').body).state,'not_found'));
check('structured documentation examples never confirm or close',()=>{for(const key of ['example','examples','sample','samples','$schema']){const r=run('application-config',JSON.stringify({[key]:{password:'SyntheticOnlyValue738'},description:'Configuration documentation'}));assert.equal(r.state,'uncertain');assert(!r.finding);assert(!r.comparable);}});
check('HTML login walls cannot close content findings',()=>{const body='<html><title>Sign in</title><body><form><input type="password"><button>Login</button></form></body></html>';for(const rule of EXPOSURE_RULES.filter(r=>r.id!=='admin-interface')){const r=run(rule.id,body);assert.equal(r.state,'blocked');assert.equal(r.comparable,false);}});
check('login form in controls prevents confirmation',()=>{const body='<form><input type="password"></form>';const r=evaluateExposure({rule:'env-config',response:{status:200,body:positive('env-config').body,url:origin+'/.env'},controls:[{status:200,body},{status:200,body}]});assert.equal(r.state,'uncertain');assert(!r.comparable);});
check('complex credential values are not placeholders merely by prefix',()=>{for(const value of ['secret738-A9ActualCredential','password293-A9RealCredential','example729-A9RealValue','test831-A9ActualValue'])assert.equal(run('env-config','APP_ENV=production\nDB_PASSWORD='+value+'\n').state,'finding');});
check('runtime stack in pre is operational evidence',()=>assert.equal(run('runtime-debug','<html><pre>Error: unhandled\n at first (/srv/app/index.js:12:8)\n at second (/srv/app/router.js:15:9)</pre></html>').state,'finding'));
check('partial archive only claims observed header',()=>{const r=run('backup-archive',positive('backup-archive').body,{status:206,truncated:true});assert.equal(r.state,'finding');assert.equal(r.finding.severity,'low');assert(r.finding.observation.includes('not inspected'));});
check('local byte cap preserves positive header evidence only',()=>{for(const error of ['body_limit','wire_limit','decoded_limit']){const found=run('backup-archive',positive('backup-archive').body,{truncated:true,error});assert.equal(found.state,'finding');assert.equal(found.finding.severity,'low');assert(found.finding.evidence.partialRead);const unknown=run('backup-archive','not enough bytes',{truncated:true,error});assert.equal(unknown.state,'uncertain');assert(!unknown.comparable);}for(const error of ['connection_dropped','decode_failed','byte_budget_exhausted','request_timeout'])assert.equal(run('backup-archive',positive('backup-archive').body,{truncated:true,error}).state,'uncertain');});
check('valid binary gzip header only, no inflation',()=>{const bytes=new Uint8Array([31,139,8,0,0,0,0,0,0,0,...Array(20).fill(0)]);const r=run('backup-archive',new TextDecoder().decode(bytes),{bytes});assert.equal(r.state,'finding');assert(r.finding.evidence.indicators.includes('archive_contents_not_examined'));});
check('source-map metadata is observation only',()=>{const r=run('source-map','{"version":3,"sources":["main.js"],"mappings":"AAAA"}');assert.equal(r.state,'observed');assert(!r.finding);assert(exposurePresentation('source-map',r.observation.evidence.indicators).observationOnly);});
check('banner/version alone does not produce CVE or product finding',()=>{assert.equal(run('elasticsearch-indices','{"version":{"number":"1.0"},"tagline":"You Know, for Search"}').state,'not_found');assert.equal(run('ignition-health','{"version":"2.0","can_execute_commands":false}').state,'not_found');});
check('planner has broad finite baseline and all rule families',()=>{const p=planExposureChecks({origin});assert(p.checks.length>100);assert.equal(new Set(p.checks.map(c=>RULES_BY_ID[c.ruleId].family)).size,9);assert.equal(new Set(p.checks.map(c=>c.ruleId+c.url)).size,p.checks.length);});
check('observed file variants and prior findings are prioritized',()=>{const p=planExposureChecks({origin,observations:{paths:['/assets/customer-app.js','/legacy/payment.php']},previousFindings:[{ruleId:'env-config',url:origin+'/.env'}]});assert.equal(p.checks[0].source,'previous_finding');for(const suffix of ['/assets/customer-app.js.map','/legacy/payment.php.bak','/legacy/payment.php.old','/legacy/payment.php~'])assert(p.checks.some(c=>c.url===origin+suffix));});
check('technology guesses cannot remove baseline',()=>{const a=planExposureChecks({origin}),b=planExposureChecks({origin,observations:{technologies:['unknown']}});assert.deepEqual(new Set(a.checks.map(c=>c.url+c.ruleId)),new Set(b.checks.map(c=>c.url+c.ruleId)));});
check('observed PHP and Spring hints promote related rules without removing baseline',()=>{for(const [technology,rule] of [['php','runtime-debug'],['spring','actuator-env']]){const a=planExposureChecks({origin}),b=planExposureChecks({origin,observations:{technologies:[technology]}});assert.deepEqual(new Set(a.checks.map(c=>c.url+c.ruleId)),new Set(b.checks.map(c=>c.url+c.ruleId)));assert.equal(b.checks.find(c=>c.ruleId===rule).priority,a.checks.find(c=>c.ruleId===rule).priority+3);}});
check('shared bounded JavaScript reads retain trailing source-map references',()=>{const body=' '.repeat(40000)+'//# sourceMappingURL=/assets/custom-debug.js.map';assert(!discoverExposureReferences({origin,body}).paths.includes('/assets/custom-debug.js.map'));assert(discoverExposureReferences({origin,body,maxBytes:262144}).paths.includes('/assets/custom-debug.js.map'));assert(!discoverExposureReferences({origin,body:' '.repeat(262144)+body,maxBytes:Infinity}).paths.includes('/assets/custom-debug.js.map'));});
check('dangerous and token-bearing paths are rejected',()=>{for(const p of ['/logout','/admin/delete.json','/restart','/generate/dump.sql','/run.php.bak','/x/../.env','/abc%2fdelete','.env','//third.test/x','/config.json?token=secret','/x#secret','/secret_abcdefghijklmnop.js'])assert.equal(isSafeExposurePath(p),false,p);});
check('reference hosts never become scan scope',()=>{const r=planExposureChecks({origin,observations:{urls:['https://external.test/config.js','https://cdn.fixture.example.test/main.js',origin+'/env.js?token=secret']}});assert(r.discoveredHosts.includes('external.test'));assert(r.discoveredHosts.includes('cdn.fixture.example.test'));assert(r.checks.every(c=>new URL(c.url).origin===origin&&!new URL(c.url).search));});
check('all observation sources feed safe discovery candidates',()=>{const r=discoverExposureReferences({origin,body:'<script src="/assets/app.js"></script>\n//# sourceMappingURL=/assets/app.js.map\n<loc>https://fixture.example.test/api/openapi.json</loc>\nDisallow: /backup/\nSitemap: https://outside.test/sitemap.xml',headers:{'x-sourcemap':'/extra.js.map'}});for(const p of ['/assets/app.js','/assets/app.js.map','/api/openapi.json','/backup/','/extra.js.map'])assert(r.paths.includes(p));assert(r.discoveredHosts.includes('outside.test'));});
check('source-map HTTP references remain candidates with no implicit external scope',()=>{const r=discoverExposureReferences({origin:origin+'/assets/main.js.map',body:JSON.stringify({version:3,sources:['../src/original.js','https://third.example.test/source.js','webpack:///private.js'],mappings:'AAAA'})});assert(r.paths.includes('/src/original.js'));assert(r.discoveredHosts.includes('third.example.test'));assert(!r.paths.includes('/private.js'));});
check('schema discovery excludes destructive read routes',()=>{const r=run('api-schema',positive('api-schema').body);assert(r.discoveries.paths.includes('/metrics'));assert(!r.discoveries.paths.includes('/delete-account'));assert(r.discoveries.hosts.includes('external.example.test'));});
check('URL display strips credentials/query/path personal data',()=>{assert.equal(safeExposureUrl('https://user:pass@fixture.example.test/private-jane.json?secret=foo#token',EXPOSURE_RULES),origin+'/[redacted-path]');});
check('all 44 upstream entries have exact provenance and individual decisions',()=>{const review=JSON.parse(fs.readFileSync(new URL('../shared/exposure/source-review.json',import.meta.url),'utf8'));assert.equal(review.templates.length,44);assert.equal(review.upstream.declared_max_requests,187);assert.equal(review.upstream.declared_max_requests_is_measured_cost,false);assert.equal(review.lynceus.code_imported,false);assert.deepEqual(review.dependencies_added,[]);for(const t of review.templates){assert.equal(t.sha256,t.reviewed_source_sha256);assert.equal(t.bytes,t.reviewed_source_bytes);assert.equal(t.template_shipped,false);assert(t.reason.length>25);assert(t.disposition);for(const id of t.replacement_rules)assert(RULES_BY_ID[id]);assert.equal(t.replacement_max_cost.length,t.replacement_rules.length);}const license=fs.readFileSync(new URL('../shared/exposure/'+review.upstream.license_file,import.meta.url));assert.equal(crypto.createHash('sha256').update(license).digest('hex'),review.upstream.license_sha256);assert.equal(review.upstream.license,'MIT');});
console.log(`exposure catalog: ${count} assertions passed; ${EXPOSURE_RULES.length} active rules / ${EXPOSURE_FAMILIES.length} families / ${EXPOSURE_FIXTURES.length} positive-negative fixtures. HTTP acceptance is a separate mandatory gate.`);
